#include <graphics.h>
#include <conio.h>
#include <math.h>

void main()
{
    int gd = DETECT, gm;
    int cx, cy, radius;
    int i, angle;
    float x, y;

    initgraph(&gd, &gm, "C:\\TURBOC3\\BGI");

    cx = getmaxx() / 2;
    cy = getmaxy() / 2;

    settextstyle(DEFAULT_FONT, HORIZ_DIR, 2);
    outtextxy(200, 20, "Circle Pattern");
    settextstyle(DEFAULT_FONT, HORIZ_DIR, 1);
    outtextxy(180, 45, "Press any key to exit");

    setcolor(WHITE);
    circle(cx, cy, 150);

    radius = 30;

    for(i = 0; i < 12; i++)
    {
        angle = i * 30;
        x = cx + 150 * cos(angle * 3.14159 / 180);
        y = cy + 150 * sin(angle * 3.14159 / 180);

        setcolor(i + 1);
        circle((int)x, (int)y, radius);
        setfillstyle(SOLID_FILL, i + 1);
        floodfill((int)x, (int)y, i + 1);
    }

    setcolor(YELLOW);
    circle(cx, cy, 40);
    setfillstyle(SOLID_FILL, YELLOW);
    floodfill(cx, cy, YELLOW);

    setcolor(LIGHTGRAY);
    for(i = 0; i < 12; i++)
    {
        angle = i * 30;
        x = cx + 150 * cos(angle * 3.14159 / 180);
        y = cy + 150 * sin(angle * 3.14159 / 180);
        line(cx, cy, (int)x, (int)y);
    }

    getch();
    closegraph();
}

#include <graphics.h>
#include <conio.h>
#include <dos.h>
#include <stdlib.h>

#define BALLS 4

void main()
{
    int gd = DETECT, gm;
    int i;

    int x[BALLS], y[BALLS];
    int dx[BALLS], dy[BALLS];
    int radius = 12;
    int color[BALLS];

    initgraph(&gd, &gm, "C:\\TURBOC3\\BGI");

    settextstyle(DEFAULT_FONT,HORIZ_DIR,2);
    outtextxy(180,10,"Turbo C Physics Demo");

    rectangle(10,50,630,470);

    randomize();

    for(i=0;i<BALLS;i++)
    {
        x[i] = random(600)+20;
        y[i] = random(350)+80;
        dx[i] = random(6)+2;
        dy[i] = random(6)+2;
        color[i] = random(15)+1;
    }

    while(!kbhit())
    {
        for(i=0;i<BALLS;i++)
        {
            setcolor(BLACK);
            setfillstyle(SOLID_FILL,BLACK);
            fillellipse(x[i],y[i],radius,radius);

            x[i]+=dx[i];
            y[i]+=dy[i];

            if(x[i]-radius<=10 || x[i]+radius>=630)
            {
                dx[i]=-dx[i];
                color[i]=random(15)+1;
                setcolor(color[i]);
                line(x[i],y[i],x[i]+random(30)-15,y[i]+random(30)-15);
            }

            if(y[i]-radius<=50 || y[i]+radius>=470)
            {
                dy[i]=-dy[i];
                color[i]=random(15)+1;
                setcolor(color[i]);
                line(x[i],y[i],x[i]+random(30)-15,y[i]+random(30)-15);
            }

            setcolor(color[i]);
            setfillstyle(SOLID_FILL,color[i]);
            fillellipse(x[i],y[i],radius,radius);
        }

        delay(15);
    }

    closegraph();
}

//  Simple Shooter Game using BGI Graphics in C++

#include <graphics.h>
#include <conio.h>
#include <dos.h>
#include <stdlib.h>
#include <stdio.h>

void main() {
    int gd = DETECT, gm;

    int playerX = 320;
    int bulletX = 0, bulletY = -1;
    int enemyX, enemyY = 0;
    int score = 0;
    char text[20];
    char ch;

    initgraph(&gd, &gm, "");

    settextstyle(DEFAULT_FONT, HORIZ_DIR, 2);
    outtextxy(180, 120, "SIMPLE SHOOTER");
    outtextxy(140, 180, "A / D  : Move");
    outtextxy(140, 210, "SPACE  : Shoot");
    outtextxy(140, 240, "ESC    : Exit");
    outtextxy(120, 300, "Press any key to start");
    getch();
    cleardevice();

    randomize();
    enemyX = rand() % (getmaxx() - 60) + 30;

    while (1) {
        cleardevice();

        rectangle(playerX - 20, 430, playerX + 20, 460);

        setcolor(RED);
        circle(enemyX, enemyY, 18);
        enemyY += 4;

        if (enemyY > getmaxy()) {
            enemyY = 0;
            enemyX = rand() % (getmaxx() - 60) + 30;
        }

        if (bulletY >= 0) {
            setcolor(YELLOW);
            line(bulletX, bulletY, bulletX, bulletY - 12);
            bulletY -= 12;
        }

        if (bulletY < 0)
            bulletY = -1;

        if (bulletY >= 0 &&
            bulletX > enemyX - 30 &&
            bulletX < enemyX + 30 &&
            bulletY > enemyY - 30 &&
            bulletY < enemyY + 30) {

            score++;
            enemyY = 0;
            enemyX = rand() % (getmaxx() - 60) + 30;
            bulletY = -1;
        }

        sprintf(text, "Score: %d", score);
        setcolor(WHITE);
        outtextxy(10, 10, text);

        if (kbhit()) {
            ch = getch();

            if (ch == 27)
                break;
            if (ch == 'a' || ch == 'A')
                playerX -= 12;
            if (ch == 'd' || ch == 'D')
                playerX += 12;
            if (ch == ' ' && bulletY == -1) {
                bulletX = playerX;
                bulletY = 420;
            }
        }

        if (playerX < 30) playerX = 30;
        if (playerX > getmaxx() - 30) playerX = getmaxx() - 30;

        delay(30);
    }

    closegraph();
}
